// spec: specs/search-header-cta.md (1.3) · кейс: .qa/tests/search-header-cta/CTA-03.md
// seed: tests/seed.user.spec.ts (user, сессия ../auth/user.json) · Android (Pixel 7) · прод, только просмотр.
import { test, expect } from '@playwright/test';
import {
  prepareReadOnly, openResults, categoryUrl, publishLink, stripOpensFilters, waitMoreBlock, CATEGORY,
} from './search-cta.helpers';

test.use({ storageState: '../auth/user.json', serviceWorkers: 'block' });

test('Вошедший: шапка с «פרסם עסק» в экране, полоса «חפש עסק» и блок «עסקים נוספים» как у гостя #839121 #1a3a08 @android @prod-safe', async ({ page, context }) => {
  await prepareReadOnly(context, true);
  await openResults(page, categoryUrl());

  await expect(page.locator('header').getByText('התחברות'), 'user вошёл (сессия жива)').toHaveCount(0);
  await expect(publishLink(page), '«פרסם עסק» в шапке вошедшего').toBeVisible();
  const fit = await page.evaluate(() => {
    const vw = window.innerWidth;
    const out = [...document.querySelectorAll('header a, header button')]
      .map((e) => e.getBoundingClientRect())
      .filter((r) => r.width > 0 && (r.left < -1 || r.right > vw + 1));
    return { outside: out.length, scrollWidth: document.documentElement.scrollWidth, vw };
  });
  expect(fit.outside, 'все элементы шапки в пределах экрана').toBe(0);
  expect(fit.scrollWidth, 'нет горизонтальной прокрутки').toBeLessThanOrEqual(fit.vw);

  const dialog = await stripOpensFilters(page);
  await expect(dialog, `в окне выбрана категория «${CATEGORY}»`).toContainText(CATEGORY);
  await page.keyboard.press('Escape');
  await expect(dialog).toBeHidden();

  await waitMoreBlock(page);
});
